import {test,expect} from 'bun:test'
import {readMigrationManifest} from '../../packages/neuvetra-database/src/staging-migrations'
import {hashManifestValue} from './create-source-manifest'
import {localName,operatorUrl,canonicalReceipts,MIGRATION,BASELINE_MANIFEST_SHA256,PROJECT,validateInventory,sameRows,sha} from './m75-common'
import {byteEntry,sameRecovery,validateRecoveryManifest,type RecoveryManifest} from './m75-recovery-manifest'
import {validateUpgradeGate} from './m75-upgrade'
const now=Date.parse('2026-09-16T07:00:00Z'),stamp=new Date(now-1000).toISOString(),digest='a'.repeat(64)
function inventory(){return {tables:[{name:'schema_migrations',count:17,sha256:digest,rowHashes:Array(17).fill(digest)},...Array.from({length:82},(_,i)=>({name:'synthetic_'+String.fromCharCode(97+Math.floor(i/26))+String.fromCharCode(97+i%26),count:0,sha256:hashManifestValue([]),rowHashes:[]}))],metadata:{tables:digest},catalogRowHashes:{tables:[digest]},roles:[],memberships:[],defaultAcls:[],dependencies:[]}}
const content=(entries:RecoveryManifest['entries']=[],schemaVersion:17|18=17):RecoveryManifest=>({profile:'neuvetra.m75.recovery-content.v1',schemaVersion,entries,sha256:hashManifestValue(entries)})
function goodGate(){
 const baseline=inventory(),manifest=content([byteEntry('mobile_diesel_reports','r1','html','old report')])
 const backup={status:'m75_encrypted_application_backup',project:PROJECT,schemaVersion:17,createdAt:stamp,archiveSha256:digest,dumpSha256:digest,inventory:baseline,recoveryManifest:manifest}
 const restore={...structuredClone(backup),status:'m75_exact_application_archive_restored',database:'m75_security_fixture',port:55472,sourceBackupCreatedAt:stamp,applicationRowsAndCatalogExact:true,runtimeRoleFlagsExact:true,allRoleFlagsAndMembershipsExact:true,applicationDefaultAclsExact:true,runtimeNoClaimDenied:true,runtimeExistingActorReadPassed:true,recoveryContentExact:true}
 const recovery={status:'m75_independent_recovery_passed',project:PROJECT,schemaVersion:17,createdAt:stamp,database:restore.database,port:55472,archiveSha256:digest,dumpSha256:digest,restoreReceiptSha256:digest,reviewerId:'independent-reviewer',applicationReadsAndDownloadsVerified:true,m73CalculationReplayVerified:true,m74CalculationReplayVerified:true,legacyDownloadsVerified:true,noMutationVerified:true,recoveryManifest:structuredClone(manifest)}
 const gate={status:'m75_independent_operator_gate_passed',project:PROJECT,createdAt:stamp,reviewedMigrationHash:MIGRATION,reviewedCommit:'b'.repeat(40),maintenanceConfirmed:true,maintenanceObservedAt:stamp,schema18ForwardRecoveryReviewed:true,providerRecoveryExclusionAccepted:true,operatorId:'operator',independentReviewerId:'independent-reviewer',restoreReceiptSha256:digest}
 const forwardContent=content([['mobile_diesel_fuel_statements','statement'],['mobile_diesel_mileage_statements','statement'],['mobile_diesel_versions','calculation'],['mobile_diesel_reports','html'],['controlled_fleet_statements','statement'],['controlled_fleet_versions','dependencies'],['controlled_fleet_reports','html'],['controlled_fleet_reports','snapshot']].map(([table,part],i)=>byteEntry(table!,String(i),part!,'synthetic '+i)),18)
 const forward={status:'m75_schema18_forward_recovery_review_passed',reviewerId:'independent-reviewer',reviewedMigrationHash:MIGRATION,schemaVersion:18,createdAt:stamp,populatedFleetRecoveryVerified:true,m73M74AndLegacyPreserved:true,runtimeReplayAndDownloadsVerified:true,noMutationVerified:true,sourceContentManifest:forwardContent,restoredContentManifest:structuredClone(forwardContent)}
 return {gate,backup,restore,recovery,forward}
}
const run=(v:ReturnType<typeof goodGate>)=>validateUpgradeGate(v.gate,v.backup,v.restore,v.recovery,v.forward,now)
test('fixed hosted project and new loopback targets only',()=>{
 for(const name of ['postgres','m74_ops_existing','m75_author_fixture','m75_ops_x;drop','M75_ops_upper'])expect(()=>localName(name,55463)).toThrow()
 expect(()=>localName('m75_ops_fresh',55472)).not.toThrow();expect(()=>localName('m75_ops_fresh',5432)).toThrow()
 for(const url of ['postgres://postgres:synthetic@localhost:5432/postgres','postgres://postgres.other:synthetic@aws-1-us-west-1.pooler.supabase.com:5432/postgres','postgres://postgres.icockcoguyadhryzydvl:synthetic@aws-1-us-west-1.pooler.supabase.com:6543/postgres'])expect(()=>operatorUrl(url)).toThrow()
})
test('canonical seventeen receipts; malformed, old, reordered and foreign target refused',async()=>{
 const m=await readMigrationManifest(),receipts=m.slice(0,17).map(({name,sha256})=>({name,sha256}))
 expect(hashManifestValue(receipts)).toBe(BASELINE_MANIFEST_SHA256)
 const tx=(rows:unknown[],project=PROJECT)=>({query:async(sql:string)=>({rows:sql.includes('schema_migrations')?rows:[{project_ref:project,profile:'neuvetra.private-synthetic-staging.v1'}]})}) as any
 if(m.length>18){
  await expect(canonicalReceipts(tx(receipts),17)).rejects.toThrow()
  await expect(canonicalReceipts(tx(m.slice(0,18).map(({name,sha256})=>({name,sha256}))),18)).rejects.toThrow()
 }else expect((await canonicalReceipts(tx(receipts),17)).length).toBe(m.length)
 for(const rows of [receipts.slice(0,16),[...receipts].reverse(),[...receipts,receipts[16]],receipts.map((r,i)=>i===16?{...r,sha256:'0'.repeat(64)}:r)])await expect(canonicalReceipts(tx(rows),17)).rejects.toThrow()
 await expect(canonicalReceipts(tx(receipts,'foreignproject'),17)).rejects.toThrow()
})
test('S01 row lists validated and compared even when table count/digest stay equal',()=>{
 const a=inventory();expect(()=>validateInventory(a)).not.toThrow()
 for(const change of [(v:any)=>v.tables[0].rowHashes[0]='f'.repeat(64),(v:any)=>v.tables[0].rowHashes.pop(),(v:any)=>v.tables[0].rowHashes.push(digest),(v:any)=>v.tables[0].rowHashes[0]='not-a-hash',(v:any)=>v.tables[0].count=-1,(v:any)=>v.tables.push(v.tables[0])]){const b=structuredClone(a);change(b);expect(()=>sameRows(a,b)).toThrow()}
 const missing=structuredClone(a);missing.tables[0]!.rowHashes.shift();expect(()=>sameRows(a,missing,true)).toThrow()
})
test('UTF8 byte evidence, null fingerprints, duplicate and omitted entries fail',()=>{
 const entry=byteEntry('mobile_diesel_versions','v1','calculation','null'),pi=byteEntry('controlled_fleet_statements','s1','statement','π\n')
 expect(pi.byteLength).toBe(3);expect(pi.sha256).toBe(sha('π\n'));expect(entry.sha256).not.toBe(sha('0'))
 expect(()=>byteEntry('t','i','p','π\n',pi.sha256,2)).toThrow();expect(()=>validateRecoveryManifest(content([entry,entry]))).toThrow()
 expect(()=>sameRecovery(content([entry]),content([]))).toThrow();expect(()=>sameRecovery(content([entry]),content([entry],18),true)).not.toThrow()
 expect(()=>sameRecovery(content([entry],18),content([entry]),true)).toThrow()
})
const gateTest=/^[a-f0-9]{64}$/.test(MIGRATION)?test:test.skip
gateTest('fresh reviewed exact17 backup and populated18 forward proof admitted',()=>expect(()=>run(goodGate())).not.toThrow())
gateTest('operator gate refuses independent stale/missing/corrupt proof variants',()=>{
 const cases:Array<(v:any)=>void>=[
  v=>v.gate.operatorId=v.gate.independentReviewerId,v=>v.gate.operatorId=' '+v.gate.independentReviewerId,v=>v.gate.operatorId=' ',v=>v.gate.createdAt='September 16, 2026 07:00:00',v=>v.gate.maintenanceConfirmed=false,v=>v.gate.maintenanceObservedAt=new Date(now-900000).toISOString(),v=>v.gate.maintenanceObservedAt=new Date(now+1).toISOString(),v=>v.gate.schema18ForwardRecoveryReviewed=false,v=>v.gate.providerRecoveryExclusionAccepted=false,v=>v.gate.reviewedMigrationHash='0'.repeat(64),
  v=>v.backup.createdAt=new Date(now-14400000).toISOString(),v=>v.forward.createdAt=new Date(now-14400000).toISOString(),v=>v.restore.createdAt=new Date(now-2000).toISOString(),v=>v.backup.schemaVersion=18,v=>v.restore.port=55463,v=>v.restore.archiveSha256='f'.repeat(64),v=>v.restore.inventory.tables[0].rowHashes[0]='f'.repeat(64),v=>v.restore.inventory.tables[0].count=1.5,
  v=>{for(const r of [v.backup,v.restore])r.inventory.tables[0].rowHashes[0]='invalid'},v=>v.recovery.m74CalculationReplayVerified=false,v=>v.recovery.m73CalculationReplayVerified=false,v=>v.recovery.legacyDownloadsVerified=false,v=>v.recovery.noMutationVerified=false,v=>v.recovery.reviewerId='author',v=>v.recovery.restoreReceiptSha256='f'.repeat(64),
  v=>v.forward.populatedFleetRecoveryVerified=false,v=>v.forward.m73M74AndLegacyPreserved=false,v=>v.forward.runtimeReplayAndDownloadsVerified=false,v=>v.forward.noMutationVerified=false,v=>{for(const key of ['sourceContentManifest','restoredContentManifest']){v.forward[key].entries=v.forward[key].entries.filter((e:any)=>e.table!=='controlled_fleet_reports');v.forward[key].sha256=hashManifestValue(v.forward[key].entries)}}
 ]
 for(const change of cases){const v=goodGate();change(v);expect(()=>run(v)).toThrow()}
})
test('operator modules have no execution side effects on import',async()=>{
 const results=await Promise.all(['./m75-backup','./m75-restore','./m75-apply','./m75-upgrade','./m75-replay'].map(path=>import(path)))
 expect(results.length).toBe(5)
})

import {test,expect} from 'bun:test'
import {createPostgresConnection,HostedWorkspaceDatabase} from '../../packages/neuvetra-database/src/hosted'
import {createM74Authority} from '../../apps/site-api/src/calculation/m74-authority'
import {decodeFleetRegister} from '../../apps/site-web/src/lib/m75-api'
import {M75_LIMITATIONS} from '../../packages/neuvetra-database/src/m75-contract'
import {M71_LIMITATIONS} from '../../packages/neuvetra-database/src/m71-contract'
import {qaId,qaHash} from './m75-independent-scenarios'
import {readMigrationManifest,provisionStagingRoster} from '../../packages/neuvetra-database/src/staging-migrations'
import {populateM75RecoveryFixture} from '../../tools/staging/m75-backend-fixture'
import {createM75Routes} from '../../apps/site-api/src/workspace/m75-routes'
const source=process.env.M75_QA_TEMPLATE??'m74_ops_restore17_1789509920941'
if(source!=='m63_integration'&&!/^m7[45]_(ops|qa|author)_[a-z0-9_]+$/.test(source))throw Error('Only an explicit isolated synthetic template is permitted')
const connect=(database:string,user='m63_test_admin')=>createPostgresConnection(`postgres://${user}@127.0.0.1:55463/${database}`,{tls:false,maxConnections:4})
async function mustReject(work:Promise<unknown>,message?:string){let error:unknown;try{await work}catch(e){error=e}expect(error instanceof Error).toBe(true);if(message)expect((error as Error).message).toContain(message)}
test.skipIf(process.env.M75_INDEPENDENT_NATIVE!=='enabled')('M75 independent native lifecycle, access and stale historical evidence',async()=>{
 const name=`m75_qa_review_${Date.now()}`,admin=connect('postgres'),authority=createM74Authority();let op:ReturnType<typeof connect>|undefined,runtime:ReturnType<typeof connect>|undefined
 const events:string[]=[]
 try{
  console.log('Native QA connecting for new isolated clone '+name)
  expect((await admin.query('select datname from pg_database where datname=$1',[name])).rows.length).toBe(0)
  console.log('Native QA creating clone');await admin.exec(`create database ${name} template ${source}`);op=connect(name)
  const manifest=await readMigrationManifest(),receipts=(await op.query<{name:string;sha256:string}>('select name,sha256 from neuvetra.schema_migrations order by name')).rows
  expect(receipts.every((r,i)=>r.name===manifest[i]?.name&&r.sha256===manifest[i]?.sha256)).toBe(true)
  await op.transaction(async tx=>{for(const m of manifest.slice(receipts.length)){await tx.exec(m.sql);await tx.query('insert into neuvetra.schema_migrations(name,sha256) values($1,$2)',[m.name,m.sha256])}})
  const seeded=await populateM75RecoveryFixture(op,name,55463),company=seeded.companyId,owner=seeded.users.owner,fleetReviewer=seeded.users.fleetReviewer
  runtime=connect(name,'neuvetra_runtime');console.log('Native QA clone ready')
  const ref=(await op.query<{project_ref:string}>('select project_ref from neuvetra.staging_target')).rows[0]!.project_ref
  const db=new(HostedWorkspaceDatabase as any)(runtime,ref) as HostedWorkspaceDatabase
  const original=(await db.findControlledFleet(owner,company,authority))!;expect(original.reconciliation.status).toBe('reconciled_bounded_synthetic');await decodeFleetRegister(original,company);events.push('native positive register and real browser decoder')
  const reportMeta=original.reports[0]!,report=(await db.findControlledFleetReport(owner,company,original.rosterId!,reportMeta.id,authority))!,proof=(await db.findControlledFleetReportProof(owner,company,original.rosterId!,reportMeta.id,authority))!
  expect(proof.reportId).toBe(report.id);expect(proof.proof.coverageVersion?.id).toBe(original.proof.coverageVersion?.id)
  await Bun.write('evaluations/research-qa/m75-independent-ui-fixture.json',JSON.stringify({register:original,report,proof,owner,fleetReviewer},null,2)+'\n')
  await mustReject(db.findControlledFleet(qaId(900),company,authority),'Private staging access required.');await mustReject(db.findControlledFleetReport(qaId(900),company,original.rosterId!,reportMeta.id,authority),'Private staging access required.');events.push('foreign unprovisioned actor denied register/report')
  await mustReject(runtime.query('update neuvetra.controlled_fleet_versions set content_sha256=$1 where company_id=$2',['0'.repeat(64),company]));events.push('runtime direct DML refused')
  const v=original.versions.at(-1)!,base={...structuredClone(v.activity),expectedDependencySha256:original.reconciliation.dependencySha256,expectedVersionId:v.id,expectedVersionSha256:v.versionSha256,correctionReason:'Independent correction',idempotencyKey:crypto.randomUUID()}
  const foreign=crypto.randomUUID();await op.query('insert into auth.users(id) values($1)',[foreign]);await provisionStagingRoster(op,{expectedProjectRef:ref,workspaceId:crypto.randomUUID(),ownerUserId:foreign,members:[]})
  expect(await db.findControlledFleet(foreign,company,authority)).toBeNull();expect(await db.findControlledFleetReport(foreign,company,original.rosterId!,report.id,authority)).toBeNull()
  const member=crypto.randomUUID();await op.query('insert into auth.users(id) values($1)',[member]);await op.query("insert into neuvetra.company_members(company_id,user_id,role) values($1,$2,'member')",[company,member]);await op.query('insert into neuvetra.staging_access(user_id,company_id,active) values($1,$2,true)',[member,company])
  expect((await db.findControlledFleet(member,company,authority))!.headVersionId).toBe(original.headVersionId)
  const memberSave=structuredClone(base);memberSave.rosterStatement!.reference+='-MEMBER';await mustReject(db.saveControlledFleet(member,company,original.rosterId,memberSave,authority));await mustReject(db.createControlledFleetReport(member,company,original.rosterId!,{expectedReconciliationSha256:original.reconciliation.contentSha256,idempotencyKey:crypto.randomUUID()},authority))
  const origin='http://127.0.0.1:37579',actors:Record<string,string>={owner,member,foreign},route=createM75Routes({database:db,authority,origin,validateUser:async token=>actors[token]?{id:actors[token]!,email:null,phone:null,fullName:null}:null})
  const http=(suffix='',token:string|null='owner',method='GET',body?:string,requestOrigin=origin)=>route(new Request(`${origin}/workspace/${company}/controlled-fleet${suffix}`,{method,headers:{origin:requestOrigin,...(token?{authorization:'Bearer '+token}:{})},...(body===undefined?{}:{body})}))
  expect((await http('',null)).status).toBe(401);expect((await http('','unknown')).status).toBe(401);expect((await http('','owner','GET',undefined,'https://unrelated.invalid')).status).toBe(403);expect((await http('','foreign')).status).toBe(404)
  const publicRegister=await http();expect(publicRegister.status).toBe(200);await decodeFleetRegister(await publicRegister.json(),company)
  expect((await http(`/${original.rosterId}/versions`,'member','POST',JSON.stringify(memberSave))).status).toBe(403);expect((await http(`/${original.rosterId}/versions`,'owner','POST','{"invalid":1,"invalid":2}')).status).toBe(422);expect((await http('','owner','PUT','{}')).status).toBe(405)
  const htmlResponse=await http(`/${original.rosterId}/reports/${report.id}/download`);expect(htmlResponse.status).toBe(200);expect(htmlResponse.headers.get('cache-control')).toBe('no-store');expect(htmlResponse.headers.get('x-content-type-options')).toBe('nosniff');expect(htmlResponse.headers.get('content-security-policy')).toContain('sandbox allow-modals');expect(await htmlResponse.text()).toBe(report.html)
  const publicProof=await http(`/${original.rosterId}/reports/${report.id}/proof`);expect(publicProof.status).toBe(200);expect(await publicProof.json()).toEqual(proof);events.push('Real public route with native database: authentication/origin/tenant/member/JSON/method refusals, exact downloads and historical proof with restrictive headers')
  await op.query('update neuvetra.staging_access set active=false where user_id=$1',[member]);await mustReject(db.findControlledFleet(member,company,authority),'Private staging access required.');events.push('Active other-tenant reads hidden; same-tenant member can read but cannot write/report; revoked access immediately refused')
  await mustReject(db.saveControlledFleet(owner,company,original.rosterId,base,authority));events.push('no-op correction refused')
  const changed=structuredClone(base);changed.rosterStatement!.reference+='-QA';const saved=await db.saveControlledFleet(owner,company,original.rosterId,changed,authority)
  const retry=await db.saveControlledFleet(owner,company,original.rosterId,changed,authority);expect(retry.id).toBe(saved.id);expect(retry.versionSha256).toBe(saved.versionSha256)
  const conflicting=structuredClone(changed);conflicting.rosterStatement!.reference+='-DIFFERENT';await mustReject(db.saveControlledFleet(owner,company,original.rosterId,conflicting,authority));events.push('exact retry reused one record; conflicting retry refused')
  let current=(await db.findControlledFleet(owner,company,authority))!;expect(current.versions.length).toBe(original.versions.length+1);expect(current.reconciliation.status).toBe('blocked');expect(current.reconciliation.findings.some(x=>x.code==='roster_review_required')).toBe(true)
  const review={versionId:saved.id,expectedVersionSha256:saved.versionSha256,expectedDependencySha256:current.reconciliation.dependencySha256,decision:'accepted_bounded_reconciliation' as const,note:'Independent bounded synthetic QA review.',acknowledgedLimitations:[...M75_LIMITATIONS],idempotencyKey:crypto.randomUUID()}
  await mustReject(db.reviewControlledFleet(owner,company,original.rosterId!,review,authority));await db.reviewControlledFleet(fleetReviewer,company,original.rosterId!,{...review,idempotencyKey:crypto.randomUUID()},authority);current=(await db.findControlledFleet(owner,company,authority))!;expect(current.reconciliation.status).toBe('reconciled_bounded_synthetic');events.push('contributor review refused, separate reviewer accepted')
  const beforeMobile=current.proof.workpaperVersions[0]!,mobileInput={...structuredClone(beforeMobile.activity),distanceMiles:'1001.000',mileageStatement:{...beforeMobile.activity.mileageStatement!,statedDistanceMiles:'1001.000'},expectedVersionId:beforeMobile.id,expectedVersionSha256:beforeMobile.versionSha256,correctionReason:'Independent mileage correction',idempotencyKey:crypto.randomUUID()}
  await db.saveMobileDiesel(owner,company,beforeMobile.worksheetId,mobileInput,authority);current=(await db.findControlledFleet(owner,company,authority))!;expect(current.reconciliation.status).toBe('blocked');expect(current.reconciliation.findings.some(x=>x.code==='dependency_stale')).toBe(true)
  const historical=await db.findControlledFleetReport(owner,company,original.rosterId!,report.id,authority),historicalProof=await db.findControlledFleetReportProof(owner,company,original.rosterId!,report.id,authority)
  expect(historical).toEqual(report);expect(historicalProof).toEqual(proof);events.push('M74 successor blocks current reconciliation while report bytes and historical proof remain exact')
  const correction=()=>{const h=current.versions.at(-1)!;return {...structuredClone(h.activity),expectedDependencySha256:current.reconciliation.dependencySha256,expectedVersionId:h.id,expectedVersionSha256:h.versionSha256,correctionReason:'Independent concurrent correction',idempotencyKey:crypto.randomUUID()}}
  const raceA=correction(),raceB=correction();raceA.rosterStatement!.reference+='-RACE-A';raceB.rosterStatement!.reference+='-RACE-B'
  const race=await Promise.allSettled([db.saveControlledFleet(owner,company,current.rosterId,raceA,authority),db.saveControlledFleet(owner,company,current.rosterId,raceB,authority)])
  expect(race.filter(x=>x.status==='fulfilled').length).toBe(1);expect(race.filter(x=>x.status==='rejected').length).toBe(1)
  const count=current.versions.length;current=(await db.findControlledFleet(owner,company,authority))!;expect(current.versions.length).toBe(count+1);expect(current.reconciliation.status).toBe('blocked');events.push('Concurrent different corrections create exactly one successor and retain current blockers')
  const same=correction();same.rosterStatement!.reference+='-SAME';const concurrentRetry=await Promise.all([db.saveControlledFleet(owner,company,current.rosterId,same,authority),db.saveControlledFleet(owner,company,current.rosterId,same,authority)]);expect(concurrentRetry[0].id).toBe(concurrentRetry[1].id);const sameCount=current.versions.length;current=(await db.findControlledFleet(owner,company,authority))!;expect(current.versions.length).toBe(sameCount+1);events.push('Concurrent exact same-key retries yield one identical immutable successor')
  const priorCoverage=current.proof.coverageVersion!,snapshot=structuredClone(priorCoverage.snapshot);snapshot.companyLabel+=' QA successor'
  const newCoverage=await db.saveCorporateInventory(owner,company,priorCoverage.inventoryId,{snapshot,expectedVersionId:priorCoverage.id,expectedVersionSha256:priorCoverage.versionSha256,correctionReason:'Independent later corporate boundary',idempotencyKey:crypto.randomUUID()})
  current=(await db.findControlledFleet(owner,company,authority))!;const rebind=correction();rebind.coverageVersionId=newCoverage.id;rebind.coverageVersionSha256=newCoverage.versionSha256;rebind.rosterStatement!.reference+='-NEW-BOUNDARY'
  await db.saveControlledFleet(owner,company,current.rosterId,rebind,authority);current=(await db.findControlledFleet(owner,company,authority))!;const blockedReport=await db.createControlledFleetReport(owner,company,current.rosterId!,{expectedReconciliationSha256:current.reconciliation.contentSha256,idempotencyKey:crypto.randomUUID()},authority)
  const nullProof=(await db.findControlledFleetReportProof(owner,company,current.rosterId!,blockedReport.id,authority))!;expect(nullProof.proof.coverageVersion!.review).toBeNull();expect(nullProof.proof.boundCoverageVersion!.review).toBeNull()
  await db.reviewCorporateInventory(seeded.users.coverageReviewer,company,newCoverage.inventoryId,{versionId:newCoverage.id,expectedVersionSha256:newCoverage.versionSha256,decision:'accepted_bounded_internal',note:'Independent later bounded coverage review',acknowledgedLimitations:[...M71_LIMITATIONS],idempotencyKey:crypto.randomUUID()})
  expect(await db.findControlledFleetReport(owner,company,current.rosterId!,blockedReport.id,authority)).toEqual(blockedReport)
  expect(await db.findControlledFleetReportProof(owner,company,current.rosterId!,blockedReport.id,authority)).toEqual(nullProof);events.push('Later coverage review leaves captured null decision and exact historical proof unchanged')
  current=(await db.findControlledFleet(owner,company,authority))!
  while(current.versions.length<40){const input=correction();input.rosterStatement!.reference='QA-CAP-VERSION-'+current.versions.length;await db.saveControlledFleet(owner,company,current.rosterId,input,authority);current=(await db.findControlledFleet(owner,company,authority))!}
  const overflow=correction();overflow.rosterStatement!.reference='QA-CAP-OVERFLOW';await mustReject(db.saveControlledFleet(owner,company,current.rosterId,overflow,authority));expect((await db.findControlledFleet(owner,company,authority))!.versions.length).toBe(40);events.push('Forty retained versions accepted; forty-first refused without an extra record')
  while(current.reports.length<40){await db.createControlledFleetReport(owner,company,current.rosterId!,{expectedReconciliationSha256:current.reconciliation.contentSha256,idempotencyKey:crypto.randomUUID()},authority);current=(await db.findControlledFleet(owner,company,authority))!}
